mapper.select:
SELECT * FROM( SELECT ROWNUM AS rn , APPV_ID , APPV_USER_ID , (SELECT USER_NM FROM TP_USER_INFO A WHERE A.USER_ID = B.APPV_USER_ID) APPV_USER_NM , APPV_TYPE , APPV_TTL , APPV_CN , APPV_STUS , APPV_STEP , DEL_YN , UPD_ID , (SELECT USER_NM FROM TP_USER_INFO A WHERE A.USER_ID = B.UPD_ID) UPD_NM , TO_CHAR(UPD_DATE, 'YY/MM/DD') UPD_DATE , REG_ID , (SELECT REG_ID FROM TP_USER_INFO A WHERE A.USER_ID = B.REG_ID) REG_NM , TO_CHAR((SELECT REG_DATE FROM TP_USER_INFO A WHERE A.USER_ID = B.REG_ID), 'YYYY/MM/DD') REG_DATE FROM TP_COMM_APPV B WHERE 1=1
AND (SELECT USER_NM FROM TP_USER_INFO WHERE USER_ID = UPD_ID) LIKE '%'|| #{receiveAppvListParamDto.updNm} ||'%'
AND APPV_TYPE LIKE '%'|| #{receiveAppvListParamDto.appvType} ||'%'
ORDER BY ${receiveAppvListParamDto.sortBy} ASC
ORDER BY ${receiveAppvListParamDto.sortBy} DESC
) WHERE rn BETWEEN #{condition.start} AND #{condition.end}
